/* Additional fresh, no-repeat mission runway for the existing global curriculum. */
'use strict';
const additionalMissionSpec = (...args) => {
  const [id,title,focus,choice,fill,order,reading,...tail]=args;
  const audio=Array.isArray(tail[0])?tail[0]:tail.slice(0,5);
  const summary=Array.isArray(tail[0])?(tail[1]||''):(tail[5]||'');
  return {id,title,focus,choice,fill,order,reading,audio,summary};
};
const listeningMissionSpec = (id,title,focus,items,summary='') => ({id,title,focus,listenItems:items,summary});
const readingMissionSpec = (id,title,focus,items,summary='') => ({id,title,focus,readItems:items,summary});
const answerOptions = (answer,wrongA,wrongB,key,salt=0) => {
  const options=[wrongA,wrongB];let hash=salt;
  for(const char of String(key))hash=(hash+char.charCodeAt(0))%997;
  options.splice(hash%3,0,answer);return options;
};
const buildAdditionalMission = (mode,spec) => {
  const questions=[];
  if(spec.listenItems){
    spec.listenItems.forEach(([audioText,prompt,answer,wrongA,wrongB],index)=>questions.push(LISTEN(audioText,prompt,answerOptions(answer,wrongA,wrongB,`${spec.id}-listen-${index}`),answer,`The speaker supports this answer; the alternatives are not supported by the audio.`,{hint:`Listen for the detail about ${spec.focus}.`})));
  }else if(spec.readItems){
    spec.readItems.forEach(([passage,prompt,answer,wrongA,wrongB],index)=>questions.push(READ(passage,prompt,answerOptions(answer,wrongA,wrongB,`${spec.id}-read-${index}`),answer,`The passage directly supports this answer; the alternatives add unsupported details.`,{hint:`Find the sentence that best answers the question about ${spec.focus}.`})));
  }else{
    const [choicePrompt,choiceAnswer,choiceWrongA,choiceWrongB]=spec.choice;
    const [fillPrompt,fillAnswer]=spec.fill;
    const [passage,readPrompt,readAnswer,readWrongA,readWrongB]=spec.reading;
    const [audioText,listenPrompt,listenAnswer,listenWrongA,listenWrongB]=spec.audio;
    questions.push(MC(choicePrompt,answerOptions(choiceAnswer,choiceWrongA,choiceWrongB,`${spec.id}-choice`),choiceAnswer,`This choice applies ${spec.focus} correctly in the stated context.`,{hint:`Check the grammar or vocabulary clue for ${spec.focus}.`}));
    questions.push(FILL(fillPrompt,fillAnswer,`The sentence requires “${fillAnswer}” to express ${spec.focus}.`,{hint:`Look for the word or form that fits ${spec.focus}.`}));
    questions.push(ORDER(`Arrange the words to form a natural sentence about ${spec.focus}.`,spec.order.trim().split(/\s+/),spec.order,`This word order makes the meaning of ${spec.focus} clear.`,{hint:'Place the subject and verb first, then keep the remaining phrase together.'}));
    questions.push(READ(passage,readPrompt,answerOptions(readAnswer,readWrongA,readWrongB,`${spec.id}-reading`),readAnswer,'The passage states this directly; the other choices add unsupported details.',{hint:`Find the passage detail that answers the question about ${spec.focus}.`}));
    questions.push(LISTEN(audioText,listenPrompt,answerOptions(listenAnswer,listenWrongA,listenWrongB,`${spec.id}-listening`),listenAnswer,'The speaker states this; the other choices are not supported by the audio.',{hint:`Listen for the detail about ${spec.focus}.`}));
  }
  const example=spec.order||spec.listenItems?.[0]?.[0]||spec.readItems?.[0]?.[0]||'';
  const summary=spec.summary||`Build confidence with ${spec.focus} through contextual questions, sentence practice, reading, and listening.`;
  return M(spec.id,spec.title,summary,20,example,questions,false);
};
