for(const [mode,missions] of Object.entries(missionBanks))for(const mission of missions){
  const presentation=missionPresentation[mode]?.[mission.id];if(presentation){mission.title=presentation[0];mission.summary=presentation[1];if(presentation[2])mission.example=presentation[2];}
  mission.xp=20;
}
